CREATE TABLE IF NOT EXISTS enterprises (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, alias TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (user_id TEXT NOT NULL REFERENCES users(id), enterprise_id TEXT NOT NULL REFERENCES enterprises(id), permission TEXT NOT NULL CHECK(permission IN ('可查看并修改','仅查看','无权访问')), PRIMARY KEY(user_id,enterprise_id));
CREATE TABLE IF NOT EXISTS invoices (enterprise_id TEXT NOT NULL REFERENCES enterprises(id), id TEXT NOT NULL, invoice_date TEXT NOT NULL, seller TEXT NOT NULL, item TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(typeof(amount_cents)='integer'), purpose TEXT NOT NULL, remarks TEXT NOT NULL, PRIMARY KEY(enterprise_id,id));
CREATE TABLE IF NOT EXISTS bank_entries (enterprise_id TEXT NOT NULL REFERENCES enterprises(id), id TEXT NOT NULL, transaction_date TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('收入','支出')), amount_cents INTEGER NOT NULL CHECK(typeof(amount_cents)='integer' AND amount_cents>0), counterparty TEXT NOT NULL, remarks TEXT NOT NULL, PRIMARY KEY(enterprise_id,id));
CREATE TABLE IF NOT EXISTS rules (id TEXT NOT NULL, version TEXT NOT NULL, name TEXT NOT NULL, effective_from TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('启用','已停用')), content TEXT NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS rule_enterprises (rule_id TEXT NOT NULL, version TEXT NOT NULL, enterprise_id TEXT NOT NULL REFERENCES enterprises(id), PRIMARY KEY(rule_id,version,enterprise_id), FOREIGN KEY(rule_id,version) REFERENCES rules(id,version));
